const originalRenderBody=renderBody;
renderBody=function(){if(ui.tab==='account')return renderAccount();return originalRenderBody()};
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(busy)return;const f=new FormData(form),type=form.dataset.form,ref=form.dataset.id;
 try{
 if(type==='contact'||type==='admin-login'){const contact=String(f.get('contact')).trim(),result=await api.request(type==='admin-login'?'/api/auth/admin':'/api/auth/start',{contact,password:f.get('password')});ui.contact=contact;ui.challenge=result.challenge;ui.demoCode=result.demoCode;ui.loginStage='otp';ui.modal=null;render();return}
 if(type==='otp'){const result=await request('/api/auth/verify',{challenge:ui.challenge,code:String(f.get('code'))});if(result.registered){ui.tab=self().role==='companion'?'home':'social';ui.draft=null}else{ui.ticket=result.registrationTicket;ui.loginStage='registration'}render();return}
 if(type==='register'){await request('/api/auth/register',{ticket:ui.ticket,role:f.get('role'),legalName:f.get('legalName'),nickname:f.get('nickname'),birthday:f.get('birthday'),city:f.get('city'),gender:f.get('gender'),inviteCode:f.get('inviteCode'),terms:f.has('terms'),privacy:f.has('privacy'),guidelines:f.has('guidelines')});ui.loginStage='contact';ui.tab=self().role==='companion'?'home':'social';ui.draft=null;render();return}
 if(type==='correction'){await act('identity-correction',{legalName:f.get('legalName'),birthday:f.get('birthday')},{message:'Correction saved. Verify your identity again.'});return}
 if(type==='connect'){await act(form.dataset.connection?'connection-revise':'connection-create',{id:form.dataset.connection,companion:ref,service:f.get('service'),hours:Number(f.get('hours')),start:f.get('start'),area:f.get('area'),note:f.get('note')},{message:'Connection request sent.',after:()=>{ui.tab='plans';ui.detail=null}});return}
 if(type==='connection-response'){await act('connection-respond',{id:ref,status:f.get('status'),reason:f.get('reason')},{message:'Response sent. The customer has been notified.'});return}
 if(type==='book'){await act('booking-create',{connection:ref,venue:f.get('venue')},{message:'Booking request sent for companion acceptance.'});return}
 if(type==='reason'){const m=ui.modal;await act(m.command,{...m.data,reason:f.get('reason')},{message:'Decision and reason recorded.'});return}
 if(type==='extension'){await act('extension-create',{id:ref,hours:Number(f.get('hours'))},{message:'Extension sent for review. The booked end time is unchanged.'});return}
 if(type==='rating'){await act('rating',{id:ref,value:Number(f.get('value'))},{message:'Rating saved for this completed booking.'});return}
 if(type==='message'){const body=String(f.get('message')).trim();const r=await act('message',{id:ref,body},{silent:true});if(r){ui.chatDraft='';render();$('[name="message"]')?.focus()}return}
 if(type==='companion-profile'){captureDraft();await act('profile-save',ui.draft,{message:'Draft saved. Submit it for moderation when ready.'});return}
 if(type==='account'){await act('account-save',{nickname:f.get('nickname'),notificationsEnabled:f.has('notificationsEnabled')},{message:'Account preferences saved.'});return}
 if(type==='support'){await act('ticket',{subject:f.get('subject'),body:f.get('body'),category:f.get('category'),reference:f.get('reference')},{message:'Support ticket created.',after:r=>{ui.modal={type:'ticket',id:r.result.id}}});return}
 if(type==='ticket-reply'){await act('ticket-reply',{id:ref,body:f.get('body'),status:f.get('status')},{close:false,message:'Reply recorded.'});return}
 if(type==='identity-review'){await act('admin-identity',{id:ref,status:f.get('status'),legalName:f.get('legalName'),birthday:f.get('birthday'),authentic:f.has('authentic'),reason:f.get('reason')},{message:'Identity review recorded.'});return}
 if(type==='profile-review'){await act('admin-profile',{id:ref,status:f.get('status'),reason:f.get('reason')},{message:'Profile decision recorded.'});return}
 if(type==='admin-member'){await act('admin-account',{id:ref,status:f.get('status'),reason:f.get('reason')},{message:'Access decision recorded.'});return}
 if(type==='refund'){await act('admin-refund',{id:ref,amountPaise:Math.round(Number(f.get('amount'))*100),reason:f.get('reason')},{close:false,message:'Refund request recorded. Confirmation awaits the gateway.'});return}
 if(type==='admin-plan'){await act('admin-plan',{name:f.get('name'),feePaise:Math.round(Number(f.get('fee'))*100),taxPaise:Math.round(Number(f.get('tax'))*100),days:Number(f.get('days')),renewal:f.get('renewal'),cancellation:f.get('cancellation'),enabled:f.has('enabled')},{message:'Membership plan updated. Existing purchases retain their terms.'});return}
 }catch(error){toast(error.message,true)}
});
document.addEventListener('change',async event=>{const el=event.target;if(el.dataset.filter){ui[el.dataset.filter]=el.value;ui.seen=[];render();return}if(el.name==='role'){const box=$('[data-guidelines]'),comp=el.value==='companion';box.hidden=!comp;box.querySelector('input').required=comp;return}if(el.hasAttribute('data-connect-service')||el.hasAttribute('data-connect-hours')){const form=el.closest('form'),m=ui.modal;m.service=form.elements.service.value;m.hours=el.hasAttribute('data-connect-service')?null:Number(form.elements.hours.value);render();return}if(/^service_\d$/.test(el.name)){$(`[data-service-config="${el.name.split('_')[1]}"]`).classList.toggle('hide',!el.checked);return}
 if(el.hasAttribute('data-photo-upload')){const file=el.files?.[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Choose a JPG, PNG or WebP file up to 10 MB.');const source=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('The photo could not be read.'));r.readAsDataURL(file)}),image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('This image could not be opened.'));img.src=source});ui.crop={source,image,zoom:1,x:.5,y:.5};openModal('crop')}catch(error){toast(error.message,true)}finally{el.value=''}return}
});
document.addEventListener('input',event=>{const el=event.target;if(el.hasAttribute('data-chat-search')){ui.chatSearch=el.value;const pos=el.selectionStart;render();const input=$('[data-chat-search]');input.focus();input.setSelectionRange(pos,pos);return}if(el.name==='message')ui.chatDraft=el.value;if(el.name==='bio')$('[data-bio-count]').textContent=`${el.value.length} / 240 characters`;if(el.dataset.priceIndex!==undefined){const amount=Number(el.value);$(`[data-customer-price="${el.dataset.priceIndex}_${el.dataset.hours}"]`).textContent=amount>0?money(Math.round(amount*100)*2.5):'—'}if(el.dataset.crop){ui.crop[el.dataset.crop]=Number(el.value);const img=$('[data-crop-preview]');img.style.transform=`scale(${ui.crop.zoom})`;img.style.objectPosition=`${ui.crop.x*100}% ${ui.crop.y*100}%`}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&ui.modal){event.preventDefault();$('[data-action="close"]')?.click()}if(event.key==='Tab'&&ui.modal){const focus=$$('[role="dialog"] button:not(:disabled),[role="dialog"] input:not([hidden]),[role="dialog"] select,[role="dialog"] textarea,[role="dialog"] a[href]').filter(x=>x.getClientRects().length);if(event.shiftKey&&document.activeElement===focus[0]){event.preventDefault();focus.at(-1)?.focus()}if(!event.shiftKey&&document.activeElement===focus.at(-1)){event.preventDefault();focus[0]?.focus()}}if(event.target.name==='message'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();event.target.closest('form').requestSubmit()}if(event.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('[role="tab"]');let index=tabs.indexOf(event.target);index=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[index].click();$$('[role="tab"]')[index]?.focus()}});
let drag=null;
function swipe(direction,ref){const card=$(`[data-swipe="${ref}"]`),finish=()=>{if(!ui.seen.includes(ref))ui.seen.push(ref);if(direction==='right')ui.detail=ref;render()};if(!card||window.matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}card.classList.add(direction==='right'?'swiping-right':'swiping-left');setTimeout(finish,320)}
document.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-swipe]');if(!card||e.target.closest('button,input,select,a')||e.button!==0)return;drag={card,id:card.dataset.swipe,x:e.clientX,y:e.clientY,dx:0,moved:false};card.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>15){drag=null;return}if(Math.abs(dx)>10)drag.moved=true;if(!drag.moved)return;drag.dx=dx;drag.card.style.transform=`translateX(${dx}px) rotate(${dx/22}deg)`;drag.card.classList.toggle('dragging-right',dx>0);drag.card.classList.toggle('dragging-left',dx<0)});
function finishDrag(){if(!drag)return;const d=drag;drag=null;d.card.style.transform='';d.card.classList.remove('dragging-left','dragging-right');if(Math.abs(d.dx)>85)swipe(d.dx>0?'right':'left',d.id)}
document.addEventListener('pointerup',finishDrag);document.addEventListener('pointercancel',()=>{if(drag){drag.card.style.transform='';drag=null}});
let media=null,remoteMedia=null,rtc=null,activeCall=null,signalsSeen=new Set();
function stopMedia(){media?.getTracks().forEach(t=>t.stop());remoteMedia?.getTracks().forEach(t=>t.stop());rtc?.close();media=null;remoteMedia=null;rtc=null;activeCall=null;signalsSeen.clear()}
function attachStreams(){if($('#local-video')&&media)$('#local-video').srcObject=media;if($('#remote-video')&&remoteMedia)$('#remote-video').srcObject=remoteMedia}
async function signal(callId,signal){await api.request('/api/action',{type:'call-signal',data:{id:callId,signal}})}
async function joinVideo(callId){if(!config.api||!config.video){toast('Video is simulated here or the media provider is disabled.',true);return}try{stopMedia();const callInfo=model.calls.find(c=>c.id===callId);media=await navigator.mediaDevices.getUserMedia({video:callInfo.kind!=='audio',audio:true});activeCall=callId;const ice=config.mode==='production'?(await api.request('/api/rtc')).iceServers:config.iceServers;rtc=new RTCPeerConnection({iceServers:ice||[]});remoteMedia=new MediaStream();rtc.ontrack=event=>{event.streams[0].getTracks().forEach(track=>remoteMedia.addTrack(track));attachStreams()};rtc.onicecandidate=event=>{if(event.candidate)signal(callId,{type:'candidate',candidate:event.candidate.toJSON()}).catch(()=>{})};media.getTracks().forEach(track=>rtc.addTrack(track,media));const call=model.calls.find(c=>c.id===callId);if(call.from===self().id){const offer=await rtc.createOffer();await rtc.setLocalDescription(offer);await signal(callId,{type:'offer',sdp:offer.sdp})}render();await receiveSignals()}catch(error){stopMedia();toast(`Could not join the introduction: ${error.message}`,true)}}
async function receiveSignals(){if(!rtc||!activeCall)return;const c=model.calls.find(c=>c.id===activeCall);if(!c||c.status!=='Accepted'){stopMedia();return}const fresh=c.signals.filter(x=>x.from!==self().id&&!signalsSeen.has(x.id));for(const item of fresh){if(item.type==='candidate'&&!rtc.remoteDescription)continue;try{if(item.type==='offer'){await rtc.setRemoteDescription({type:'offer',sdp:item.sdp});const answer=await rtc.createAnswer();await rtc.setLocalDescription(answer);await signal(c.id,{type:'answer',sdp:answer.sdp})}else if(item.type==='answer'){await rtc.setRemoteDescription({type:'answer',sdp:item.sdp})}else await rtc.addIceCandidate(item.candidate);signalsSeen.add(item.id)}catch(e){toast('The call connection needs to be restarted.',true);stopMedia();break}}}
setInterval(async()=>{if(!model||!config.api||busy)return;try{const result=await api.request('/api/session'),changed=JSON.stringify(result.view)!==JSON.stringify(model);use(result);await receiveSignals();if(changed&&!document.activeElement?.matches('input,select,textarea')&&!$('[data-form="companion-profile"]')&&!ui.crop)render()}catch(error){if(error.status===401){stopMedia();model=null;ui.modal=null;render()}}},3000);
async function boot(){try{const res=await fetch('api/config',{cache:'no-store'});if(document.querySelector('meta[name="hl-runtime"]')?.content==='public-demo'&&(res.status===404||res.ok&&!res.headers.get('content-type')?.includes('application/json'))){const {DemoAPI}=await import('./demo-api.js?v=20261010-system-v2.1');api=new DemoAPI();config=api.config}else{if(!res.ok)throw new Error('Backend unavailable. Please refresh shortly.');config=await res.json();api=new ServerAPI()}if(config.mode==='demo')accounts=await api.request('/api/demo/accounts');try{await request('/api/session');ui.tab=self().role==='companion'?'home':'social';ui.draft=null}catch(error){if(error.status!==401)throw error}render();if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}catch(error){$('#app').innerHTML=`<main class="page"><section class="card"><h1>High Life is reconnecting.</h1><p>${escape(error.message)}</p><button class="button" data-action="reload">Refresh your browser</button></section></main>`}}
boot();
